/// <summary>
/// Provides a hardcoded authenticated user on the server and persists the auth state
/// into PersistentComponentState so WebAssembly can read it after the handoff.
/// </summary>
public sealed class ServerAuthenticationStateProvider : AuthenticationStateProvider, IDisposable
{
    private readonly PersistentComponentState _persistentComponentState;
    private readonly PersistingComponentStateSubscription _subscription;

    private static readonly AuthenticationState _authState = CreateAuthState();

